 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_PROPULSION_PARTICLE_CHECK"));}private static void need(boolean yes,String message){if(!yes){done=true;throw new AssertionError("Plume GPU generation="+generation+" "+message);}}
