 private static void prepare()throws Exception{need(!NativePropulsionParticleRenderType.INSTANCE.isTranslucent(),"Source before-translucent pass");var reference=JsonParser.parseString(Files.readString(Path.of(System.getenv("VANDOR_PROPULSION_PARTICLE_PIXELS")))).getAsJsonObject();for(String name:NAMES){var image=sprite(name).contents().getOriginalImage();need(image.getWidth()==8&&image.getHeight()==8,"full original glyph "+name);if(generation==0){var expected=reference.getAsJsonArray(name);for(int y=0;y<8;y++)for(int x=0;x<8;x++){int actual=image.getPixelRGBA(x,y),old=expected.get(y*8+x).getAsInt();if((actual>>>24)!=0||(old>>>24)!=0)need(actual==old,"actual Source visible RGBA "+name+" "+x+","+y);}}else if(name.equals("critical_hit")){need(image.getPixelRGBA(6,5)==0,"resource-pack hole preserved; no canonical correction");need(image.getPixelRGBA(2,2)==0xffff8000,"resource-pack blue visible content preserved");}else if(name.equals("effect_0"))need(image.getPixelRGBA(2,2)==0x11ffffff,"faint resource-pack alpha preserved");}prepared=true;}
 private static final class Sink implements PropulsionBillboard.Sink {VertexConsumer buffer;PoseStack.Pose pose;TextureAtlasSprite sprite;int tile;public void vertex(float x,float y,float z,float u,float v,int c,int light){float localU=PropulsionBillboard.localU(tile,u),localV=PropulsionBillboard.localV(tile,v);buffer.addVertex(pose.pose(),x,y,z).setUv(sprite.getU0()+(sprite.getU1()-sprite.getU0())*localU,sprite.getV0()+(sprite.getV1()-sprite.getV0())*localV).setColor(c&255,(c>>>8)&255,(c>>>16)&255,(c>>>24)&255).setLight(light);}}
