 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event)throws Exception{if(done||!enabled()||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var mc=Minecraft.getInstance();if(mc.getWindow().getGuiScaledWidth()<640||mc.getWindow().getGuiScaledHeight()<360){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();return;}if(!prepared)prepare();var gui=event.getGuiGraphics();gui.flush();RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();float start=RenderSystem.getShaderFogStart(),end=RenderSystem.getShaderFogEnd();RenderSystem.setShaderFogStart(100000);RenderSystem.setShaderFogEnd(100001);mc.gameRenderer.lightTexture().turnOnLightLayer();try{for(int i=0;i<5;i++)glyph(gui,i,70+i*120,75,400,false,false);glyph(gui,2,180,240,600,frames<5,true);glyph(gui,2,440,240,600,true,true);}finally{mc.gameRenderer.lightTexture().turnOffLightLayer();RenderSystem.setShaderFogStart(start);RenderSystem.setShaderFogEnd(end);RenderSystem.depthMask(true);RenderSystem.disableBlend();}frames++;}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||!enabled()||(frames!=5&&frames!=12))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double scale=mc.getWindow().getGuiScale();int x0=(int)(115*scale),y0=(int)(175*scale),width=(int)(130*scale),height=(int)(130*scale);if(frames==5){negative=new int[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++)negative[y*width+x]=image.getPixelRGBA(x0+x,y0+y);return;}var debug=mc.gameDirectory.toPath().resolve("screenshots/propulsion-particles-"+generation+".png");Files.createDirectories(debug.getParent());image.writeToFile(debug);int difference=0;for(int y=0;y<height;y++)for(int x=0;x<width;x++)if(negative[y*width+x]!=image.getPixelRGBA(x0+x,y0+y))difference++;if(generation==1)need(difference>1000,"faint Source shader versus stock discard negative pixels="+difference);if(generation==1){int center=image.getPixelRGBA((int)(180*scale),(int)(240*scale));need(Math.abs((center&255)-47)<=1&&Math.abs(((center>>>8)&255)-54)<=1&&Math.abs(((center>>>16)&255)-62)<=1,"Source faint alpha blends over background rather than drawing opaque white");}changed+=difference;for(int i=0;i<5;i++){int ink=0,blue=0,red=0;for(int y=(int)(30*scale);y<(int)(120*scale);y++)for(int x=(int)((25+i*120)*scale);x<(int)((115+i*120)*scale);x++){int c=image.getPixelRGBA(x,y);if((c&0xffffff)!=0x302820)ink++;if(((c>>>16)&255)>(c&255)*1.4)blue++;if((c&255)>((c>>>16)&255)*1.4)red++;}need(ink>200,"visible source glyph "+i);if(i==0||i==3)need(red>100,"asymmetric Source red emitter");if(i==1||i==4)need(blue>100,"asymmetric Source blue emitter");}var path=mc.gameDirectory.toPath().resolve("screenshots/propulsion-particles-"+generation+".png");Files.createDirectories(path.getParent());image.writeToFile(path);System.out.println("[vandorlabs][propulsion-particles] generation="+generation+" negativePixels="+difference);}if(generation++==0){frames=0;prepared=false;var packs=mc.getResourcePackRepository();packs.reload();need(packs.getAvailableIds().contains("file/propulsion-particle-override"),"private override pack available");packs.addPack("file/propulsion-particle-override");mc.reloadResourcePacks();return;}done=true;System.out.println("[vandorlabs][propulsion-particles] title PASS fiveStyles/SourceVisibleRGBA/canonicalPixelCorrection/packOverride/faintShader/reload negativePixels="+changed+" software primitive only");mc.stop();}
